{
  "title": "信号的呼唤",
  "scene": "你正漂浮在维修通道内，耳边响着飞船系统的警报声。氧气供给显示严重不足，你需要尽快找到解决方案。突然，一个未知的无线电频道发来信号：\"这是SOS呼叫，如果你收到，请回复！\"。你发现这个频道的发射源似乎来自飞船的某个角落。另一边，你的队友小李通过内部通讯器紧急呼叫你：\"老王，赶快到生命维持系统室来，我可能找到问题所在了！\"",
  "goal": "找到并解决问题，确保氧气供给",
  "clue": "未知信号可能来自被困的船员，而非外部",
  "choices": [
    {
      "id": "A",
      "text": "回复未知信号",
      "outcome": "你尝试回复，但信号源是飞船内部的一个封闭舱室，里面似乎有被困的船员。你决定先解救他们，再处理氧气问题。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "前往生命维持系统室",
      "outcome": "你立刻前往生命维持系统室，发现小李已经找到了故障点并开始修理。你加入他，成功修复了系统，氧气供给恢复了正常。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "先检查氧气罐",
      "outcome": "你决定先检查氧气罐，但发现罐内氧气几乎耗尽，无法解决问题。你决定返回，听取小李的建议。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
